watch(
  () => route.name,
  (newName, oldName) => {
    const wasWebsocket = oldName === 'Websocket';
    const nowWebsocket = newName === 'Websocket';
    if (wasWebsocket && !nowWebsocket) {
      // User left the WebSocket tab – stop reconnection attempts
      clearReconnectTimer();
      if (socket.value) socket.value.close();
    } else if (!wasWebsocket && nowWebsocket) {
      // User entered the WebSocket tab – (re)connect
      connect();
    }
  }
);

