export interface WebhookPayload {
  event: string;
  data: Record<string, any>;
  // Store timestamp as Date for runtime, but serialize as ISO string
  timestamp: Date;
}

/**
 * Helper to safely parse a serialized payload where timestamp is an ISO string.
 */
export function parseSerializedPayload(serialized: {
  event: string;
  data: Record<string, any>;
  timestamp: string;
}): WebhookPayload {
  const { event, data, timestamp } = serialized;
  const parsedDate = new Date(timestamp);
  if (isNaN(parsedDate.getTime())) {
    throw new Error('Invalid timestamp in webhook payload');
  }
  return { event, data, timestamp: parsedDate };
}

